const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');

const pageLoadBlueprint = async function () {
    // URL passed as environment variable from Terraform
    const URL = process.env.TARGET_URL;

    if (!URL) {
      throw new Error("TARGET_URL environment variable is missing.");
    }

    let page = await synthetics.getPage();
    
    log.info(`Checking URL: ${URL}`);
    const response = await page.goto(URL, {waitUntil: 'domcontentloaded', timeout: 30000});
    
    // If ALB returns 500, we know the system threw our "SYSTEM_HACKED" error
    if (response.status() === 500) {
        throw new Error("ALB returned 500! System is Defaced. Triggering Healing Process!");
    }

    log.info("Website is healthy.");
};

exports.handler = async () => {
    return await pageLoadBlueprint();
};
